// Validate status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Parse response
const users = pm.response.json();

// Validate non-empty array
pm.test("Response is a non-empty array", function () {
    pm.expect(users).to.be.an("array");
    pm.expect(users.length).to.be.above(0);
});

// Validate user information
pm.test("Users contain required fields", function () {

    users.forEach(function (user) {

        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name");
        pm.expect(user).to.have.property("email");

    });
});

// Save one user ID
const selectedUser = users[0];

pm.collectionVariables.set(
    "userId",
    selectedUser.id
);

// Save original user details
pm.collectionVariables.set(
    "originalUser",
    JSON.stringify(selectedUser)
);

console.log("Selected User ID:", selectedUser.id);

// Get original user data from GET request
const user = JSON.parse(
    pm.collectionVariables.get("originalUser")
);

// Generate dynamic updated data
const timestamp = Date.now();

const updatedName = "Tanny Updated " + timestamp;
const updatedEmail = "tanny" + timestamp + "@example.com";
const updatedCompanyName = "SQA Automation Company";

// Store updated data
pm.collectionVariables.set("updatedName", updatedName);
pm.collectionVariables.set("updatedEmail", updatedEmail);
pm.collectionVariables.set("updatedCompanyName", updatedCompanyName);

// Preserve unchanged fields
pm.collectionVariables.set("originalUsername", user.username);
pm.collectionVariables.set("originalAddress", JSON.stringify(user.address));
pm.collectionVariables.set("originalPhone", user.phone);
pm.collectionVariables.set("originalWebsite", user.website);
pm.collectionVariables.set("originalCatchPhrase", user.company.catchPhrase);
pm.collectionVariables.set("originalBs", user.company.bs);

// Validate status code
pm.test("PUT status code is 200", function () {
    pm.response.to.have.status(200);
});

const response = pm.response.json();

const savedId = Number(
    pm.collectionVariables.get("userId")
);

const updatedName = pm.collectionVariables.get(
    "updatedName"
);

// Validate returned ID
pm.test("Returned ID matches saved ID", function () {
    pm.expect(response.id).to.eql(savedId);
});

// Validate phone is not empty
pm.test("Phone should not be empty", function () {
    pm.expect(response.phone).to.be.a("string");
    pm.expect(response.phone.trim()).to.not.equal("");
});

// Validate updated name
pm.test("Updated name should match", function () {
    pm.expect(response.name).to.eql(updatedName);
});

// Validate updated email
pm.test("Updated email should match", function () {
    pm.expect(response.email).to.eql(
        pm.collectionVariables.get("updatedEmail")
    );
});

// Validate updated company name
pm.test("Company name should be updated", function () {
    pm.expect(response.company.name).to.eql(
        pm.collectionVariables.get("updatedCompanyName")
    );
});

console.log("PUT Response:", response);
